import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { loadFont } from '../../sfnt/src/font.js';
import { jsBrotli } from '../src/brotli.js';

// W3C WOFF 2.0 suite cases glyph once failed: generated by `npm run fetch` from the suite's own
// generators (w3c/woff2-tests @ dd31222) into third_party/w3c/. w3c-expected.json holds metrics as
// decoded by Google's reference decoder (google/woff2 @ fb9c337) and read by fontTools. The full
// suite, with fontTools and Google's reference decoder as oracles, is `npm run conform`.
const dir = new URL('../../third_party/w3c/', import.meta.url);
const load = (f) => loadFont(new Uint8Array(readFileSync(new URL(f, dir))), { brotli: jsBrotli });
const expected = JSON.parse(readFileSync(new URL('./w3c-expected.json', import.meta.url), 'utf8'));
/** Left side bearings straight from the (reconstructed) hmtx table. */
const lsbs = (font) => {
  const h = font.tables.get('hmtx'), hh = font.tables.get('hhea');
  const dv = new DataView(h.buffer, h.byteOffset, h.byteLength), nh = new DataView(hh.buffer, hh.byteOffset).getUint16(34);
  return Array.from({ length: font.numGlyphs }, (_, g) => (g < nh ? dv.getInt16(g * 4 + 2) : dv.getInt16(nh * 4 + (g - nh) * 2)));
};

test('transformed hmtx (WOFF2 §5.4) is reconstructed: advances and side bearings match the reference decoder', async () => {
  for (const name of ['valid-005', 'tabledata-transform-hmtx-001', 'datatypes-alt-255uint16-001']) {
    const f = await load(`${name}.woff2`);
    assert.equal(f.tag, 'Ok', `${name}: ${JSON.stringify(f.error)}`);
    const want = expected[name];
    assert.deepEqual(Array.from({ length: want.numGlyphs }, (_, g) => f.value.advance(g)), want.advances, `${name} advances`);
    assert.deepEqual(lsbs(f.value), want.lsbs, `${name} lsbs`);
  }
});

test('round trip: the decoded font equals the original .ttf (advances, side bearings)', async () => {
  const [w, t] = await Promise.all([load('roundtrip-hmtx-lsb-001.woff2'), load('roundtrip-hmtx-lsb-001.ttf')]);
  assert.equal(w.tag, 'Ok'); assert.equal(t.tag, 'Ok');
  assert.deepEqual(lsbs(w.value), lsbs(t.value));
  for (let g = 0; g < t.value.numGlyphs; g++) assert.equal(w.value.advance(g), t.value.advance(g));
});

test('rejected as the spec requires: extraneous or overlapping blocks, a loca with the wrong declared length', async () => {
  for (const [name, why] of [
    ['blocks-extraneous-data-003', 'BadLayout'], ['blocks-extraneous-data-007', 'BadLayout'], ['blocks-overlap-003', 'BadLayout'],
    ['tabledata-bad-origlength-loca-001', 'Invariant'],
  ]) {
    const f = await load(`${name}.woff2`);
    assert.equal(f.tag, 'Err', `${name} must be rejected`);
    assert.match(JSON.stringify(f.error), new RegExp(why), name);
  }
});

test('collections are a typed UnsupportedCollection, not a confusing DuplicateTable', async () => {
  const f = await load('roundtrip-collection-order-001.woff2');
  assert.equal(f.tag, 'Err');
  assert.match(JSON.stringify(f.error), /UnsupportedCollection/);
});
